<?php
declare(strict_types=1);
$data = (array) ($billingContext['data'] ?? []);
$format = static fn (mixed $value, string $kind): string => $kind === 'money' ? number_format((float) $value, 2, '.', ' ') . ' AZN' : number_format((float) $value, 0, '.', ' ');
?>
<div data-billing-overview>
<div class="billing-kpis"><?php foreach ((array) ($data['kpis'] ?? []) as $kpi): ?><div class="billing-kpi" data-billing-kpi><span><?= e((string) ($kpi['label'] ?? '-')); ?></span><strong><?= e($format($kpi['value'] ?? 0, (string) ($kpi['kind'] ?? 'count'))); ?></strong></div><?php endforeach; ?></div>
<div class="billing-actions portal-section-gap"><a class="portal-primary-btn portal-inline-link" href="billing-customers.php">Musteriler</a><a class="portal-ghost-btn portal-inline-link" href="billing-payments.php">Odenisler</a><a class="portal-ghost-btn portal-inline-link" href="billing-balances.php">Balans ve borclar</a><a class="portal-ghost-btn portal-inline-link" href="billing-statistics.php">Billing statistikasi</a></div>
<div class="billing-panels"><section class="billing-panel"><div class="portal-card-head"><div><strong>Diqqet teleb edenler</strong><small>Borc ve yaxinlasan servis bitmeleri.</small></div><a href="billing-balances.php" class="portal-ghost-btn portal-inline-link">Hamisi</a></div><div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>Abonent</th><th>Borc</th><th>Bitme</th></tr></thead><tbody><?php foreach ((array) ($data['alerts'] ?? []) as $row): ?><tr data-billing-row><td><strong><?= e((string) ($row['subscriber_code'] ?? '-')); ?></strong><br><small><?= e((string) ($row['full_name'] ?? '-')); ?></small></td><td><?= e($format($row['debt_amount'] ?? 0, 'money')); ?></td><td><?= e((string) ($row['expires_at'] ?? '-')); ?></td></tr><?php endforeach; ?><?php if (($data['alerts'] ?? []) === []): ?><tr><td colspan="3" class="billing-empty">Aktiv xeberdarliq yoxdur.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="billing-panel"><div class="portal-card-head"><div><strong>Son odenisler</strong><small>Billing daxilinde son qeydler.</small></div><a href="billing-payments.php" class="portal-ghost-btn portal-inline-link">Hamisi</a></div><div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>Abonent</th><th>Provider</th><th>Mebleg</th></tr></thead><tbody><?php foreach ((array) ($data['recent'] ?? []) as $row): ?><tr data-billing-row><td><strong><?= e((string) ($row['subscriber_code'] ?? '-')); ?></strong><br><small><?= e((string) ($row['full_name'] ?? '-')); ?></small></td><td><?= e((string) ($row['payment_method'] ?? '-')); ?></td><td><?= e($format($row['amount'] ?? 0, 'money')); ?></td></tr><?php endforeach; ?><?php if (($data['recent'] ?? []) === []): ?><tr><td colspan="3" class="billing-empty">Odenis yoxdur.</td></tr><?php endif; ?></tbody></table></div></section></div>
</div>
